using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;
class Icons {
 static void Main(string[] a){using(var bmp=new Bitmap(1,1)){bmp.SetPixel(0,0,Color.White);bmp.Save(Path.Combine(a[0],"white.png"),ImageFormat.Png);}foreach(string name in new[]{"edit","deck","player","save","back","forward"})foreach(string state in new[]{"normal","hover","pressed"})Draw(name,state,a[0]);}
 static void Draw(string name,string state,string dir){bool white=name=="back"||name=="forward";Color ink=white?Color.FromArgb(240,242,251):Color.FromArgb(84,222,255);if(state=="hover")ink=Color.FromArgb(245,255,255);if(state=="pressed")ink=Color.FromArgb(70,181,225);using(var bmp=new Bitmap(160,160)){using(var g=Graphics.FromImage(bmp)){g.SmoothingMode=SmoothingMode.AntiAlias;g.CompositingQuality=CompositingQuality.HighQuality;var outer=new RectangleF(7,7,146,146);using(var glow=new Pen(Color.FromArgb(state=="hover"?90:36,ink),8))g.DrawEllipse(glow,outer);using(var ring=new LinearGradientBrush(outer,Color.FromArgb(240,white?205:90,white?215:210,white?240:245),Color.FromArgb(235,white?64:31,white?85:76,white?131:121),LinearGradientMode.Vertical))g.FillEllipse(ring,outer);using(var disk=new LinearGradientBrush(new RectangleF(13,13,134,134),Color.FromArgb(252,27,47,63),Color.FromArgb(252,3,6,13),LinearGradientMode.Vertical))g.FillEllipse(disk,13,13,134,134);using(var p=new Pen(Color.FromArgb(state=="hover"?220:115,ink),2))g.DrawEllipse(p,16,16,128,128);using(var p=new Pen(Color.FromArgb(55,205,240,255),1)){g.DrawArc(p,11,11,138,138,190,160);g.DrawArc(p,22,22,116,116,10,60);}using(var pen=new Pen(ink,5)){pen.StartCap=pen.EndCap=LineCap.Round;pen.LineJoin=LineJoin.Round;using(var fill=new SolidBrush(ink)){
 if(name=="back"||name=="forward"){PointF[] tri=name=="back"?new[]{new PointF(59,80),new PointF(101,53),new PointF(101,107)}:new[]{new PointF(102,80),new PointF(60,53),new PointF(60,107)};g.FillPolygon(fill,tri);}
 if(name=="edit"){g.DrawRectangle(pen,48,43,48,72);g.DrawLine(pen,59,57,83,57);g.DrawLine(pen,59,69,78,69);g.FillPolygon(fill,new[]{new PointF(76,101),new PointF(80,86),new PointF(109,57),new PointF(119,67),new PointF(90,96)});g.DrawLine(pen,106,60,117,70);}
 if(name=="deck"){g.DrawRectangle(pen,44,43,44,59);g.DrawLines(pen,new[]{new PointF(55,107),new PointF(55,113),new PointF(100,113),new PointF(100,64)});g.DrawLine(pen,117,55,117,106);g.DrawLines(pen,new[]{new PointF(107,67),new PointF(117,55),new PointF(127,67)});g.DrawLines(pen,new[]{new PointF(107,94),new PointF(117,106),new PointF(127,94)});}
 if(name=="player"){g.DrawEllipse(pen,49,47,23,23);g.DrawArc(pen,40,70,42,30,180,180);g.DrawEllipse(pen,88,79,23,23);g.DrawArc(pen,78,102,43,29,180,180);g.DrawLines(pen,new[]{new PointF(87,46),new PointF(116,46),new PointF(116,66)});g.DrawLines(pen,new[]{new PointF(107,58),new PointF(116,67),new PointF(124,58)});g.DrawLines(pen,new[]{new PointF(75,119),new PointF(46,119),new PointF(46,105)});g.DrawLines(pen,new[]{new PointF(38,112),new PointF(46,103),new PointF(55,111)});}
 if(name=="save"){g.DrawPolygon(pen,new[]{new PointF(46,42),new PointF(102,42),new PointF(116,57),new PointF(116,117),new PointF(46,117)});g.DrawRectangle(pen,60,43,35,25);g.DrawRectangle(pen,61,87,40,30);g.DrawLine(pen,89,48,89,61);}
 }}}bmp.Save(Path.Combine(dir,name+"-"+state+".png"),ImageFormat.Png);}}
}
